window.YW_ASK = [{"k": ["watch", "warning", "difference", "advisory"], "q": "What's the difference between a watch and a warning?", "a": "A <b>watch</b> means conditions are favorable, so be prepared. A <b>warning</b> means the hazard is happening or about to happen, so take action now. An <b>advisory</b> is a less serious hazard that still calls for caution.", "u": "/guides/watch-vs-warning.html", "t": "Watch vs. warning"}, {"k": ["tornado", "shelter", "basement", "mobile home"], "q": "Where should I shelter from a tornado?", "a": "Go to a basement, storm cellar or the lowest floor of a sturdy building. With no basement, use a small interior room with no windows, such as a closet, a bathroom or an interior hallway, and cover your head and neck. Mobile homes don't offer protection.", "u": "/guides/tornado-watch-vs-warning.html", "t": "Tornado safety"}, {"k": ["lightning", "thunder", "outside", "how long", "30"], "q": "How long should I wait after thunder?", "a": "When thunder roars, go indoors. Lightning can strike as far as 10 miles from a storm. Stay inside until 30 minutes after the last thunder you hear.", "u": "/guides/lightning-safety.html", "t": "Lightning safety"}, {"k": ["lightning", "car", "tent", "shelter", "safe"], "q": "Is a tent or picnic shelter safe from lightning?", "a": "No. Safe shelter is a substantial building with wiring and plumbing, or a hard-topped metal vehicle with the windows up. Tents, picnic shelters and open-sided structures don't protect you.", "u": "/guides/lightning-safety.html", "t": "Lightning safety"}, {"k": ["severe", "thunderstorm", "hail", "58", "mph"], "q": "What makes a thunderstorm 'severe'?", "a": "NWS calls a thunderstorm severe when it has hail 1 inch or larger, wind gusts of 58 mph or more, or a tornado.", "u": "/guides/thunderstorm-lightning-safety.html", "t": "Severe thunderstorm safety"}, {"k": ["flood", "water", "drive", "road", "car", "inches"], "q": "How much water can sweep away a car?", "a": "12 inches of moving water can carry away most cars, and 2 feet can carry away SUVs and trucks. Just 6 inches of fast-moving water can knock an adult off their feet. Turn Around, Don't Drown.", "u": "/guides/flood-safety-turn-around.html", "t": "Flood safety"}, {"k": ["hurricane", "category", "saffir", "simpson", "scale"], "q": "What do hurricane categories mean?", "a": "On the Saffir-Simpson scale: Category 1 is 74–95 mph, 2 is 96–110, 3 is 111–129, 4 is 130–156, and 5 is 157 mph or higher. Categories 3–5 are 'major'. The scale covers wind only, not surge or flooding.", "u": "/guides/hurricane-preparedness.html", "t": "Hurricane preparedness"}, {"k": ["hurricane", "watch", "warning", "hours", "36", "48"], "q": "When are hurricane watches and warnings issued?", "a": "A hurricane watch is issued 48 hours before tropical-storm-force winds are expected; a warning, 36 hours before.", "u": "/guides/hurricane-preparedness.html", "t": "Hurricane preparedness"}, {"k": ["hurricane", "season", "when", "june", "november"], "q": "When is hurricane season?", "a": "The Atlantic season runs from June 1 to November 30. The eastern Pacific season starts May 15.", "u": "/guides/hurricane-preparedness.html", "t": "Hurricane preparedness"}, {"k": ["cone", "track", "hurricane"], "q": "Am I safe if I'm outside the hurricane cone?", "a": "Not necessarily. The cone shows the probable track of the storm's <i>center</i>. Surge, heavy rain and wind often reach far outside it.", "u": "/guides/hurricane-preparedness.html", "t": "Hurricane preparedness"}, {"k": ["radar", "colors", "dbz", "red", "purple", "magenta"], "q": "What do the radar colors mean?", "a": "Colors show reflectivity in dBZ. Greens are light rain, yellow and orange are heavier rain, red is very heavy rain, and magenta, purple or white often means hail. Color scales vary between apps.", "u": "/guides/how-to-read-weather-radar.html", "t": "How to read weather radar"}, {"k": ["hook", "echo", "bow", "radar", "rotation"], "q": "What's a hook echo or a bow echo?", "a": "A hook echo is a hook shape on the back of a supercell that can indicate rotation and a possible tornado. A bow echo is a bulging line of storms that often brings damaging straight-line winds.", "u": "/guides/how-to-read-weather-radar.html", "t": "How to read weather radar"}, {"k": ["pressure", "barometer", "falling", "rising", "inhg", "hpa"], "q": "What does falling pressure mean?", "a": "Steadily falling pressure often means an approaching low and worsening weather. Rising pressure often means clearing. Standard sea-level pressure is 29.92 inHg (1013.25 hPa).", "u": "/guides/barometric-pressure-and-weather.html", "t": "Barometric pressure"}, {"k": ["kit", "emergency", "water", "gallon", "supplies", "outage"], "q": "What goes in an emergency kit?", "a": "Ready.gov's basics: one gallon of water per person per day for several days, non-perishable food, a battery or hand-crank radio, a flashlight, a first-aid kit, extra batteries, a whistle, chargers and a backup battery, plus medicines and copies of documents.", "u": "/guides/weather-emergency-kit.html", "t": "Emergency kit"}, {"k": ["no signal", "off-grid", "offgrid", "satellite", "backcountry", "noaa radio", "weather radio"], "q": "How do I get warnings with no cell signal?", "a": "Carry a NOAA Weather Radio: it broadcasts NWS warnings 24/7 on 162.400–162.550 MHz and needs no cell signal. Some newer phones can text by satellite. In the app, Off-Grid Safety (free) helps you text your saved location to emergency contacts. Carrier message and data rates may apply.", "u": "/guides/off-grid-emergency-weather.html", "t": "Off-grid emergency weather"}, {"k": ["price", "cost", "premium", "subscription", "how much"], "q": "How much is Premium?", "a": "The app is free on Android and iPhone. Premium is $4.99/month or $47.99/year through Google Play, or $4.99/month on iPhone through the App Store.", "u": "/pricing.html", "t": "More"}, {"k": ["cams", "camera", "webcam", "webcoos"], "q": "Does the app have weather cams?", "a": "Yes. Nearby cams from USGS, NOAA, Windy.com and WebCOOS coastal cams, plus YouTube live streams, are free.", "u": "/features.html", "t": "More"}, {"k": ["gemma", "ai", "briefing", "offline"], "q": "What is the AI briefing?", "a": "Tap a tab (NOW, 6–24H, or 2D through 10D) for a short summary of that window. NOW is free. With Premium you can download Google's Gemma 3 (1B) model to write briefings on your phone, offline.", "u": "/features.html", "t": "More"}, {"k": ["lite", "slow", "old phone"], "q": "The app is slow on my phone. Any tips?", "a": "Turn on Lite mode in Settings. Radar then loads overlays gradually and caps the heavy layers.", "u": "/support.html", "t": "More"}];
